package scheduler

import (
	"context"
	"errors"
	"log/slog"
	"strconv"
	"strings"
	"time"

	"github.com/yourorg/soar/internal/blob"
	"github.com/yourorg/soar/internal/store"
	"github.com/yourorg/soar/internal/store/opensearch"
	"github.com/yourorg/soar/internal/store/opensearch/schema"
)

// Retention runs the cleanup jobs of spec 5.2 for state indices. Time-series indices
// (alerts, raw, step runs, timeline, audit) are removed by ISM policies generated by
// `soar migrate`; idempotency and soar-seen by the TTL purge. Work in progress is
// never deleted: executions count from ended_at, cases from closed_at.
type Retention struct {
	OS     *opensearch.Client
	St     *store.Store
	Blob   blob.Blob
	Prefix string
	File   string
	Log    *slog.Logger
	Now    func() time.Time
}

func (r *Retention) now() time.Time {
	if r.Now != nil {
		return r.Now()
	}
	return time.Now().UTC()
}

func parseRetention(v string) (time.Duration, bool) {
	if v == "" || v == schema.TTL {
		return 0, false
	}
	n, err := strconv.Atoi(v[:len(v)-1])
	if err != nil || n <= 0 {
		return 0, false
	}
	if strings.HasSuffix(v, "d") {
		return time.Duration(n) * 24 * time.Hour, true
	}
	return time.Duration(n) * time.Hour, true
}

// Run executes one cleanup pass.
func (r *Retention) Run(ctx context.Context) error {
	cfg, err := schema.LoadRetention(r.File)
	if err != nil {
		return err
	}
	now := r.now()
	cut := func(class string) (string, bool) {
		d, ok := parseRetention(cfg.For(class))
		if !ok {
			return "", false
		}
		return now.Add(-d).Format(time.RFC3339Nano), true
	}
	idx := func(e string) string { return r.Prefix + "-" + e }
	total := 0
	del := func(index string, q map[string]any) error {
		n, err := opensearch.DeleteByQuery(ctx, r.OS, index, q)
		total += n
		return err
	}
	terminal := []any{"succeeded", "failed", "cancelled", "timed_out"}

	if c, ok := cut("executions"); ok {
		if err := del(idx("executions"), boolQ(terms("status", terminal), rangeLT("ended_at", c))); err != nil {
			return err
		}
		if err := del(idx("approvals"), boolQ(terms("status", []any{"approved", "rejected", "expired", "cancelled"}), rangeLT("updated_at", c))); err != nil {
			return err
		}
	}
	// fired timers are only history
	if err := del(idx("timers"), boolQ(term("fired", true), rangeLT("fired_at", now.Add(-24*time.Hour).Format(time.RFC3339Nano)))); err != nil {
		return err
	}
	if c, ok := cut("cases"); ok {
		var ids []any
		cursor := ""
		for {
			page, err := r.St.Cases.List(ctx, store.ListQuery{
				Terms:  map[string][]string{"status": {"closed"}},
				Ranges: []store.Range{{Field: "closed_at", Lte: c}}, Limit: 200, After: cursor,
			})
			if err != nil {
				return err
			}
			for _, cs := range page.Items {
				ids = append(ids, cs.ID)
				for _, ev := range cs.Evidence { // objects first: a dangling case is never left pointing nowhere
					if r.Blob == nil {
						break
					}
					if ref, err := blob.ParseRef(ev.Ref); err == nil {
						if err := r.Blob.Delete(ctx, ref); err != nil && !errors.Is(err, blob.ErrNotFound) {
							r.Log.Warn("could not delete evidence object", "case", cs.ID, "ref", ev.Ref, "error", err.Error())
						}
					}
				}
			}
			if page.NextCursor == "" || len(ids) >= 5000 {
				break
			}
			cursor = page.NextCursor
		}
		if len(ids) > 0 {
			// children first, so a crash never leaves orphans without their case
			for _, child := range []string{"case-tasks", "case-alerts"} {
				if err := del(idx(child), terms("case_id", ids)); err != nil {
					return err
				}
			}
			if err := del(idx("cases"), terms("id", ids)); err != nil {
				return err
			}
			r.Log.Info("expired closed cases", "count", len(ids))
		}
	}
	if c, ok := cut("observables"); ok {
		q := boolQ(rangeLT("last_seen", c))
		q["bool"].(map[string]any)["must_not"] = []any{map[string]any{"exists": map[string]any{"field": "case_ids"}}}
		if err := del(idx("observables"), q); err != nil {
			return err
		}
	}
	if total > 0 {
		r.Log.Info("retention cleanup", "deleted", total)
	}
	return nil
}

func term(f string, v any) map[string]any { return map[string]any{"term": map[string]any{f: v}} }
func terms(f string, v []any) map[string]any {
	return map[string]any{"terms": map[string]any{f: v}}
}

func rangeLT(f, v string) map[string]any {
	return map[string]any{"range": map[string]any{f: map[string]any{"lt": v}}}
}

func boolQ(filters ...map[string]any) map[string]any {
	fs := make([]any, len(filters))
	for i, f := range filters {
		fs[i] = f
	}
	return map[string]any{"bool": map[string]any{"filter": fs}}
}
